def is_prefix_free(codes):
    """True when no word in codes is the start of another word."""
    for i, a in enumerate(codes):
        for j, b in enumerate(codes):
            if b.startswith(a):
                return False
    return True

def is_prefix_free(codes):
    """True when no word in codes is the start of another word."""
    for i, a in enumerate(codes):
        for j, b in enumerate(codes):
            if a != b and b.startswith(a):
                return False
    return True
